//! Two build-time tasks:
//!
//! 1. **i18n**: generate `src/i18n_keys.rs` from `lang/zh.json` (one `k::` constant per key)
//!    and validate key-set parity, key naming, reference existence and dead keys -- moving
//!    typos and missing translations from runtime to build time.
//! 2. **Icon**: embed `assets/icon.ico` into the Windows exe resource.
//!
//! Ordering: i18n must run before the non-Windows early return (only the icon is platform-specific).

use std::collections::{BTreeMap, BTreeSet};
use std::fmt::Write as _;
use std::path::{Path, PathBuf};

/// Generated file. Compare before writing; unchanged content is not written, otherwise
/// every build refreshes mtime and cargo keeps recompiling.
const GENERATED: &str = "src/i18n_keys.rs";

fn main() {
    i18n();
    embed_icon();
}

fn manifest_dir() -> PathBuf {
    PathBuf::from(std::env::var("CARGO_MANIFEST_DIR").expect("CARGO_MANIFEST_DIR is not set"))
}

/// Read a flat JSON object (key -> value). Build-time errors are fatal; no silent fallback.
fn load_flat_json(path: &Path) -> BTreeMap<String, String> {
    let text = std::fs::read_to_string(path)
        .unwrap_or_else(|e| panic!("i18n: failed to read {}: {e}", path.display()));
    serde_json::from_str(&text).unwrap_or_else(|e| {
        panic!(
            "i18n: failed to parse {} (expected a flat string object): {e}",
            path.display()
        )
    })
}

/// Key naming: `prefix_role_name`, lowercase letters/digits/underscores, optional dot segments.
fn key_is_valid(k: &str) -> bool {
    let Some((head, _)) = k.split_once('_') else {
        return false;
    };
    if !matches!(head, "ui" | "msg" | "err" | "tpl") {
        return false;
    }
    k.bytes()
        .all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'_' || b == b'.')
}

/// Key id -> constant name (`ui_btn_edit` -> `UI_BTN_EDIT`).
fn const_name(id: &str) -> String {
    id.chars()
        .map(|c| {
            if c.is_ascii_alphanumeric() {
                c.to_ascii_uppercase()
            } else {
                '_'
            }
        })
        .collect()
}

fn i18n() {
    let root = manifest_dir();
    println!("cargo:rerun-if-changed=lang/zh.json");
    println!("cargo:rerun-if-changed=lang/en.json");

    let zh = load_flat_json(&root.join("lang").join("zh.json"));
    let en = load_flat_json(&root.join("lang").join("en.json"));

    // Check 1: the zh and en key sets must match exactly
    let missing: Vec<&String> = zh.keys().filter(|k| !en.contains_key(*k)).collect();
    let extra: Vec<&String> = en.keys().filter(|k| !zh.contains_key(*k)).collect();
    if !missing.is_empty() || !extra.is_empty() {
        panic!(
            "i18n: zh.json and en.json key sets differ\n  en missing {}: {missing:?}\n  en extra {}: {extra:?}",
            missing.len(),
            extra.len()
        );
    }

    // Check 2: key naming
    let bad: Vec<&String> = zh.keys().filter(|k| !key_is_valid(k)).collect();
    if !bad.is_empty() {
        panic!(
            "i18n: {} invalid keys (prefix must be ui_/msg_/err_/tpl_): {bad:?}",
            bad.len()
        );
    }

    // Generate src/i18n_keys.rs
    let mut out = String::new();
    out.push_str("//! Generated by build.rs from lang/zh.json -- do not edit (overwritten on the next build).\n");
    out.push_str("//!\n");
    out.push_str("//! Use `t(k::UI_BTN_EDIT)` at call sites: a typo is a compile error and IDE find-references work.\n");
    out.push_str("//! Add new strings to both zh.json and en.json, then use `k::UI_XXX` in code.\n\n");
    out.push_str("pub mod k {\n");
    for (id, zh_value) in &zh {
        // Generated doc comments use the English translation; UI values are looked up at runtime.
        let value = en.get(id).unwrap_or(zh_value);
        // Strings may contain real newlines; escape them so the `///` doc line is not truncated.
        let doc = value.replace('\r', "").replace('\n', "\\n");
        writeln!(out, "    /// {doc}").expect("i18n: generation failed");
        writeln!(out, "    pub const {}: &str = \"{id}\";", const_name(id))
            .expect("i18n: generation failed");
    }
    out.push_str("}\n");

    let gen_path = root.join(GENERATED);
    let old = std::fs::read_to_string(&gen_path).unwrap_or_default();
    if old != out {
        std::fs::write(&gen_path, out)
            .unwrap_or_else(|e| panic!("i18n: failed to write {}: {e}", gen_path.display()));
    }

    // Check 3: cross-check source references against language keys
    let mut used: BTreeSet<String> = BTreeSet::new();
    let mut refs: Vec<(PathBuf, String)> = Vec::new();
    for file in collect_rs(&root.join("src")) {
        let rel = file.strip_prefix(&root).unwrap_or(&file).to_path_buf();
        if rel.to_string_lossy().replace('\\', "/") == GENERATED {
            continue; // generated file: not a reference and not a rerun trigger (avoids a self-trigger loop)
        }
        println!("cargo:rerun-if-changed={}", rel.display());
        let Ok(text) = std::fs::read_to_string(&file) else {
            continue;
        };
        for name in scan_k_refs(&text) {
            used.insert(name.to_ascii_lowercase());
            refs.push((rel.clone(), name));
        }
    }

    // 3a: references to unknown keys -> fatal
    let known: BTreeSet<String> = zh.keys().cloned().collect();
    let unknown: Vec<String> = used
        .iter()
        .filter(|n| !known.contains(*n))
        .map(|n| {
            let hits: Vec<String> = refs
                .iter()
                .filter(|(_, r)| r.to_ascii_lowercase() == *n)
                .map(|(p, _)| p.display().to_string())
                .collect();
            format!("{n} (used in {})", hits.join(", "))
        })
        .collect();
    if !unknown.is_empty() {
        panic!(
            "i18n: source references {} keys missing from lang/zh.json: {unknown:?}",
            unknown.len()
        );
    }

    // 3b: dead keys (present in the table, never referenced) -> fatal
    let dead: Vec<&String> = zh.keys().filter(|k| !used.contains(*k)).collect();
    if !dead.is_empty() {
        panic!(
            "i18n: lang/zh.json has {} keys never referenced by k:: (remove them or add call sites): {dead:?}",
            dead.len()
        );
    }
}

/// Extract all `k::IDENT` constant names from source text (uppercase + underscore/digits).
///
/// Must exclude tails of longer paths: `crate::pak::available` also contains `k::`;
/// without a preceding-character check it would be mistaken for a language key.
fn scan_k_refs(text: &str) -> Vec<String> {
    let bytes = text.as_bytes();
    let mut out = Vec::new();
    let mut i = 0;
    while let Some(pos) = text[i..].find("k::") {
        let start = i + pos + 3;
        let prev = text[..i + pos].chars().next_back();
        if prev.is_some_and(|c| c.is_ascii_alphanumeric() || c == '_' || c == ':') {
            i = start;
            continue;
        }
        let mut end = start;
        while end < bytes.len() {
            let c = bytes[end] as char;
            if c.is_ascii_uppercase() || c.is_ascii_digit() || c == '_' {
                end += 1;
            } else {
                break;
            }
        }
        if end > start {
            out.push(text[start..end].to_string());
        }
        i = end.max(start);
    }
    out
}

/// Recursively collect all `.rs` files under `dir`.
fn collect_rs(dir: &Path) -> Vec<PathBuf> {
    let mut out = Vec::new();
    let Ok(rd) = std::fs::read_dir(dir) else {
        return out;
    };
    for e in rd.flatten() {
        let p = e.path();
        if p.is_dir() {
            out.extend(collect_rs(&p));
        } else if p.extension().is_some_and(|x| x == "rs") {
            out.push(p);
        }
    }
    out.sort();
    out
}

/// Embed `assets/icon.ico` into the exe. winresource needs a local resource compiler (rc.exe / windres);
/// if unavailable, downgrade to a warning: the exe has no custom icon but the build still succeeds.
fn embed_icon() {
    if std::env::var("CARGO_CFG_TARGET_OS").as_deref() != Ok("windows") {
        return;
    }
    println!("cargo:rerun-if-changed=assets/icon.ico");
    let mut res = winresource::WindowsResource::new();
    res.set_icon("assets/icon.ico");
    if let Err(e) = res.compile() {
        println!("cargo:warning=failed to embed the icon (the exe will use the default icon): {e}");
    }
}
